import { FunctionalComponent } from 'preact';
import { ENGINES } from '../../utils';
import Popover from '../../../../shared/Popover';
import { engineIcons } from '../../utils';

import styles from './styles.module.scss';

interface Props {
  handleChooseEngine: (e, value) => void;
  onClose: (e) => void;
  engine: string;
}

/*
{eng[0] === 'oh' && (
  <div className={styles.shellsText}>
    <div className={styles.shellsEmoji}>👈</div>Get more shells for each
    search
  </div>
)}
 */

const ChooseEnginePopover: FunctionalComponent<Props> = ({
  handleChooseEngine,
  onClose,
  engine,
}: Props) => (
  <Popover className={styles.enginePopover} onClose={onClose}>
    {!engine && (
      <h2 className={styles.title}>Choose your default search engine</h2>
    )}

    {Object.entries(ENGINES).map((eng) => (
      <div
        key={eng[0]}
        onClick={(e): void => handleChooseEngine(e, eng[0])}
        className={`${styles.engineWrapper} ${
          eng[0] === engine ? styles.selected : ''
        }`}
      >
        <img
          src={engineIcons[eng[0]]}
          width="19"
          height="19"
          alt={engine}
        />

        <p>{eng[1].v}</p>
      </div>
    ))}
  </Popover>
);

export default ChooseEnginePopover;
